1	import React from 'react';
2	import { describe, test, expect, vi } from 'vitest';
3	import { render, screen, fireEvent } from '@testing-library/react';
4	import { ChakraProvider } from '@chakra-ui/react';
5	import { IntlProvider } from 'react-intl';
6	import theme from 'app/theme';
7	import { ZimmQuantityStepper } from './index';
8	import { Button } from 'app/components/ui-kits/atoms/zimmButton/zimmButton.css';
9	import { spacing } from 'app/theme/foundation/spacing';
10	import { OPACITY_ICON_DISABLED } from 'app/components/ui-kits/zimmCartItemShared';
11	
12	// ZimmIcon imports the base SFCC icons barrel, which throws under Vitest (SVG imports resolve to
13	// raw path strings in this environment, not components) — see testing.md's Known gap. ZimmButton
14	// itself renders for real in every test below (not mocked): only its own leaf icon is stubbed, so
15	// the real ariaDisabled/onClick-suppression wiring this suite depends on is genuinely exercised
16	// end-to-end, not assumed from ZimmButton's own separate test suite.
17	vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({ ZimmIcon: () => null }));
18	
19	const DECREMENT_NAME = 'Decrease quantity';
20	const INCREMENT_NAME = 'Increase quantity';
21	
22	const renderStepper = (props: Partial<React.ComponentProps<typeof ZimmQuantityStepper>> = {}) => {
23	  const onDecrement = vi.fn();
24	  const onIncrement = vi.fn();
25	  render(
26	    <IntlProvider locale="en">
27	      <ChakraProvider theme={theme}>
28	        <ZimmQuantityStepper quantity={3} max={5} onDecrement={onDecrement} onIncrement={onIncrement} {...props} />
29	      </ChakraProvider>
30	    </IntlProvider>,
31	  );
32	  return { onDecrement, onIncrement };
33	};
34	
35	describe('ZimmQuantityStepper — quantity = 1 (min boundary, State 1)', () => {
36	  test('decrement button carries aria-disabled="true"', () => {
37	    renderStepper({ quantity: 1 });
38	    expect(screen.getByRole('button', { name: DECREMENT_NAME })).toHaveAttribute('aria-disabled', 'true');
39	  });
40	
41	  test('clicking decrement at quantity 1 does NOT call onDecrement — quantity stays 1', () => {
42	    const { onDecrement } = renderStepper({ quantity: 1 });
43	    fireEvent.click(screen.getByRole('button', { name: DECREMENT_NAME }));
44	    expect(onDecrement).not.toHaveBeenCalled();
45	    expect(screen.getByText('1')).toBeInTheDocument();
46	  });
47	
48	  test('increment button is NOT disabled when only the lower bound is hit', () => {
49	    renderStepper({ quantity: 1, max: 5 });
50	    expect(screen.getByRole('button', { name: INCREMENT_NAME })).not.toHaveAttribute('aria-disabled', 'true');
51	  });
52	});
53	
54	describe('ZimmQuantityStepper — quantity > 1, below max (State 2, both enabled)', () => {
55	  test('decrement calls onDecrement with exactly quantity - 1, exactly once', () => {
56	    const { onDecrement } = renderStepper({ quantity: 3, max: 5 });
57	    fireEvent.click(screen.getByRole('button', { name: DECREMENT_NAME }));
58	    expect(onDecrement).toHaveBeenCalledTimes(1);
59	    expect(onDecrement).toHaveBeenCalledWith(2);
60	  });
61	
62	  test('increment calls onIncrement with exactly quantity + 1, exactly once', () => {
63	    const { onIncrement } = renderStepper({ quantity: 3, max: 5 });
64	    fireEvent.click(screen.getByRole('button', { name: INCREMENT_NAME }));
65	    expect(onIncrement).toHaveBeenCalledTimes(1);
66	    expect(onIncrement).toHaveBeenCalledWith(4);
67	  });
68	
69	  test('neither button carries aria-disabled', () => {
70	    renderStepper({ quantity: 3, max: 5 });
71	    expect(screen.getByRole('button', { name: DECREMENT_NAME })).not.toHaveAttribute('aria-disabled', 'true');
72	    expect(screen.getByRole('button', { name: INCREMENT_NAME })).not.toHaveAttribute('aria-disabled', 'true');
73	  });
74	});
75	
76	describe('ZimmQuantityStepper — quantity at max (State 3)', () => {
77	  test('increment button carries aria-disabled="true"', () => {
78	    renderStepper({ quantity: 5, max: 5 });
79	    expect(screen.getByRole('button', { name: INCREMENT_NAME })).toHaveAttribute('aria-disabled', 'true');
80	  });
81	
82	  test('clicking increment at max does NOT call onIncrement — quantity stays at max', () => {
83	    const { onIncrement } = renderStepper({ quantity: 5, max: 5 });
84	    fireEvent.click(screen.getByRole('button', { name: INCREMENT_NAME }));
85	    expect(onIncrement).not.toHaveBeenCalled();
86	    expect(screen.getByText('5')).toBeInTheDocument();
87	  });
88	
89	  test('decrement remains enabled at the max boundary', () => {
90	    renderStepper({ quantity: 5, max: 5 });
91	    expect(screen.getByRole('button', { name: DECREMENT_NAME })).not.toHaveAttribute('aria-disabled', 'true');
92	  });
93	});
94	
95	describe('ZimmQuantityStepper — isUnavailable (State 4, fully OOS/unavailable)', () => {
96	  test('both buttons carry aria-disabled="true", even mid-range (not just at a quantity bound)', () => {
97	    renderStepper({ quantity: 3, max: 5, isUnavailable: true });
98	    expect(screen.getByRole('button', { name: DECREMENT_NAME })).toHaveAttribute('aria-disabled', 'true');
99	    expect(screen.getByRole('button', { name: INCREMENT_NAME })).toHaveAttribute('aria-disabled', 'true');
100	  });
101	
102	  test('clicking either button calls neither callback — both are inert', () => {
103	    const { onDecrement, onIncrement } = renderStepper({ quantity: 3, max: 5, isUnavailable: true });
104	    fireEvent.click(screen.getByRole('button', { name: DECREMENT_NAME }));
105	    fireEvent.click(screen.getByRole('button', { name: INCREMENT_NAME }));
106	    expect(onDecrement).not.toHaveBeenCalled();
107	    expect(onIncrement).not.toHaveBeenCalled();
108	    expect(screen.getByText('3')).toBeInTheDocument();
109	  });
110	});
111	
112	describe('ZimmQuantityStepper — accessible names (State 6)', () => {
113	  test('decrement and increment buttons each resolve a distinct, real accessible name', () => {
114	    renderStepper({ quantity: 3, max: 5 });
115	    // getByRole with `name` already fails if the accessible name is missing/wrong — these two
116	    // succeeding proves both aria-labels are present, not merely that *some* button exists.
117	    expect(screen.getByRole('button', { name: DECREMENT_NAME })).toBeInTheDocument();
118	    expect(screen.getByRole('button', { name: INCREMENT_NAME })).toBeInTheDocument();
119	  });
120	});
121	
122	/**
123	 * States 5 and 7 are both about ZimmButton's own `icon` variant/size — a Tier 2 file this build
124	 * step composes but does not modify (see index.tsx's docblock). Reading the exported recipe
125	 * object directly proves the real, resolved theme values without rendering (per this step's own
126	 * brief: "assert this from the recipe/theme's resolved values, not by rendering in an actual
127	 * browser") and without re-testing what zimmButton's own suite already covers.
128	 */
129	describe('ZimmButton icon variant — resolved theme values (composed here, State 5 & 7)', () => {
130	  test('State 7 — icon touch target minW/minH both resolve to var(--zimm-scale-xl)', () => {
131	    // Button.sizes is typed optional by Chakra's defineStyleConfig, but zimmButton.css.ts always
132	    // passes a sizes object with an `icon` entry — guaranteed non-null at runtime. Same
133	    // justification zimmButton.css.test.ts's own `Button.sizes!.social` assertions already use.
134	    const icon = Button.sizes!.icon as Record<string, unknown>;
135	    expect(icon.minW).toBe('var(--zimm-scale-xl)');
136	    expect(icon.minH).toBe('var(--zimm-scale-xl)');
137	  });
138	
139	  test('State 7 — var(--zimm-scale-xl) resolves to at least 24 CSS px (WCAG 2.2 AA SC 2.5.8)', () => {
140	    // foundation/spacing.ts's `xl` is the source `--zimm-scale-xl` derives from (see
141	    // zimmTokens.ts's "reference, not a second copy" pattern) — confirmed here as 1.5rem, which
142	    // is 24px at the browser default 16px root font-size.
143	    const REM_TO_PX = 16;
144	    expect(spacing.xl).toBe('1.5rem');
145	    expect(parseFloat(spacing.xl) * REM_TO_PX).toBeGreaterThanOrEqual(24);
146	  });
147	
148	  test('State 5 — icon variant _disabled opacity equals the SAME OPACITY_ICON_DISABLED this stepper reads for its own value display', () => {
149	    // Button.variants is typed optional by Chakra's defineStyleConfig, but zimmButton.css.ts
150	    // always passes a variants object with an `icon` entry — guaranteed non-null at runtime.
151	    const icon = Button.variants!.icon as Record<string, unknown>;
152	    const disabledState = icon._disabled as Record<string, unknown>;
153	    expect(disabledState.opacity).toBe(OPACITY_ICON_DISABLED);
154	  });
155	
156	  test("State 5 — the icon variant's focus-visible outline is genuinely different from its default (resting) outline, not merely a separate key", () => {
157	    const icon = Button.variants!.icon as Record<string, unknown>;
158	    const focusVisible = icon._focusVisible as Record<string, unknown>;
159	    // The resting/default icon style declares no top-level `outline` at all (bg/border/color/
160	    // transition only — see zimmButton.css.ts) — only _focusVisible adds one. Comparing the two
161	    // resolved values directly (rather than assuming focus differs from default because Chakra
162	    // models them as separate keys) proves the two states are actually visually different.
163	    expect(icon.outline).toBeUndefined();
164	    expect(focusVisible.outline).toBe('var(--zimm-focus-ring)');
165	    expect(focusVisible.outline).not.toBe(icon.outline);
166	  });
167	});
