import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen, fireEvent } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { IntlProvider } from 'react-intl';
import theme from 'app/theme';
import { ZimmQuantityStepper } from './index';
import { Button } from 'app/components/ui-kits/atoms/zimmButton/zimmButton.css';
import { spacing } from 'app/theme/foundation/spacing';
import { OPACITY_ICON_DISABLED } from 'app/components/ui-kits/zimmCartItemShared';

// ZimmIcon imports the base SFCC icons barrel, which throws under Vitest (SVG imports resolve to
// raw path strings in this environment, not components) — see testing.md's Known gap. ZimmButton
// itself renders for real in every test below (not mocked): only its own leaf icon is stubbed, so
// the real ariaDisabled/onClick-suppression wiring this suite depends on is genuinely exercised
// end-to-end, not assumed from ZimmButton's own separate test suite.
vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({ ZimmIcon: () => null }));

const DECREMENT_NAME = 'Decrease quantity';
const INCREMENT_NAME = 'Increase quantity';

const renderStepper = (props: Partial<React.ComponentProps<typeof ZimmQuantityStepper>> = {}) => {
  const onDecrement = vi.fn();
  const onIncrement = vi.fn();
  render(
    <IntlProvider locale="en">
      <ChakraProvider theme={theme}>
        <ZimmQuantityStepper quantity={3} max={5} onDecrement={onDecrement} onIncrement={onIncrement} {...props} />
      </ChakraProvider>
    </IntlProvider>,
  );
  return { onDecrement, onIncrement };
};

describe('ZimmQuantityStepper — quantity = 1 (min boundary, State 1)', () => {
  test('decrement button carries aria-disabled="true"', () => {
    renderStepper({ quantity: 1 });
    expect(screen.getByRole('button', { name: DECREMENT_NAME })).toHaveAttribute('aria-disabled', 'true');
  });

  test('clicking decrement at quantity 1 does NOT call onDecrement — quantity stays 1', () => {
    const { onDecrement } = renderStepper({ quantity: 1 });
    fireEvent.click(screen.getByRole('button', { name: DECREMENT_NAME }));
    expect(onDecrement).not.toHaveBeenCalled();
    expect(screen.getByText('1')).toBeInTheDocument();
  });

  test('increment button is NOT disabled when only the lower bound is hit', () => {
    renderStepper({ quantity: 1, max: 5 });
    expect(screen.getByRole('button', { name: INCREMENT_NAME })).not.toHaveAttribute('aria-disabled', 'true');
  });
});

describe('ZimmQuantityStepper — quantity > 1, below max (State 2, both enabled)', () => {
  test('decrement calls onDecrement with exactly quantity - 1, exactly once', () => {
    const { onDecrement } = renderStepper({ quantity: 3, max: 5 });
    fireEvent.click(screen.getByRole('button', { name: DECREMENT_NAME }));
    expect(onDecrement).toHaveBeenCalledTimes(1);
    expect(onDecrement).toHaveBeenCalledWith(2);
  });

  test('increment calls onIncrement with exactly quantity + 1, exactly once', () => {
    const { onIncrement } = renderStepper({ quantity: 3, max: 5 });
    fireEvent.click(screen.getByRole('button', { name: INCREMENT_NAME }));
    expect(onIncrement).toHaveBeenCalledTimes(1);
    expect(onIncrement).toHaveBeenCalledWith(4);
  });

  test('neither button carries aria-disabled', () => {
    renderStepper({ quantity: 3, max: 5 });
    expect(screen.getByRole('button', { name: DECREMENT_NAME })).not.toHaveAttribute('aria-disabled', 'true');
    expect(screen.getByRole('button', { name: INCREMENT_NAME })).not.toHaveAttribute('aria-disabled', 'true');
  });
});

describe('ZimmQuantityStepper — quantity at max (State 3)', () => {
  test('increment button carries aria-disabled="true"', () => {
    renderStepper({ quantity: 5, max: 5 });
    expect(screen.getByRole('button', { name: INCREMENT_NAME })).toHaveAttribute('aria-disabled', 'true');
  });

  test('clicking increment at max does NOT call onIncrement — quantity stays at max', () => {
    const { onIncrement } = renderStepper({ quantity: 5, max: 5 });
    fireEvent.click(screen.getByRole('button', { name: INCREMENT_NAME }));
    expect(onIncrement).not.toHaveBeenCalled();
    expect(screen.getByText('5')).toBeInTheDocument();
  });

  test('decrement remains enabled at the max boundary', () => {
    renderStepper({ quantity: 5, max: 5 });
    expect(screen.getByRole('button', { name: DECREMENT_NAME })).not.toHaveAttribute('aria-disabled', 'true');
  });
});

describe('ZimmQuantityStepper — isUnavailable (State 4, fully OOS/unavailable)', () => {
  test('both buttons carry aria-disabled="true", even mid-range (not just at a quantity bound)', () => {
    renderStepper({ quantity: 3, max: 5, isUnavailable: true });
    expect(screen.getByRole('button', { name: DECREMENT_NAME })).toHaveAttribute('aria-disabled', 'true');
    expect(screen.getByRole('button', { name: INCREMENT_NAME })).toHaveAttribute('aria-disabled', 'true');
  });

  test('clicking either button calls neither callback — both are inert', () => {
    const { onDecrement, onIncrement } = renderStepper({ quantity: 3, max: 5, isUnavailable: true });
    fireEvent.click(screen.getByRole('button', { name: DECREMENT_NAME }));
    fireEvent.click(screen.getByRole('button', { name: INCREMENT_NAME }));
    expect(onDecrement).not.toHaveBeenCalled();
    expect(onIncrement).not.toHaveBeenCalled();
    expect(screen.getByText('3')).toBeInTheDocument();
  });
});

describe('ZimmQuantityStepper — accessible names (State 6)', () => {
  test('decrement and increment buttons each resolve a distinct, real accessible name', () => {
    renderStepper({ quantity: 3, max: 5 });
    // getByRole with `name` already fails if the accessible name is missing/wrong — these two
    // succeeding proves both aria-labels are present, not merely that *some* button exists.
    expect(screen.getByRole('button', { name: DECREMENT_NAME })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: INCREMENT_NAME })).toBeInTheDocument();
  });
});

/**
 * States 5 and 7 are both about ZimmButton's own `icon` variant/size — a Tier 2 file this build
 * step composes but does not modify (see index.tsx's docblock). Reading the exported recipe
 * object directly proves the real, resolved theme values without rendering (per this step's own
 * brief: "assert this from the recipe/theme's resolved values, not by rendering in an actual
 * browser") and without re-testing what zimmButton's own suite already covers.
 */
describe('ZimmButton icon variant — resolved theme values (composed here, State 5 & 7)', () => {
  test('State 7 — icon touch target minW/minH both resolve to var(--zimm-scale-xl)', () => {
    // Button.sizes is typed optional by Chakra's defineStyleConfig, but zimmButton.css.ts always
    // passes a sizes object with an `icon` entry — guaranteed non-null at runtime. Same
    // justification zimmButton.css.test.ts's own `Button.sizes!.social` assertions already use.
    const icon = Button.sizes!.icon as Record<string, unknown>;
    expect(icon.minW).toBe('var(--zimm-scale-xl)');
    expect(icon.minH).toBe('var(--zimm-scale-xl)');
  });

  test('State 7 — var(--zimm-scale-xl) resolves to at least 24 CSS px (WCAG 2.2 AA SC 2.5.8)', () => {
    // foundation/spacing.ts's `xl` is the source `--zimm-scale-xl` derives from (see
    // zimmTokens.ts's "reference, not a second copy" pattern) — confirmed here as 1.5rem, which
    // is 24px at the browser default 16px root font-size.
    const REM_TO_PX = 16;
    expect(spacing.xl).toBe('1.5rem');
    expect(parseFloat(spacing.xl) * REM_TO_PX).toBeGreaterThanOrEqual(24);
  });

  test('State 5 — icon variant _disabled opacity equals the SAME OPACITY_ICON_DISABLED this stepper reads for its own value display', () => {
    // Button.variants is typed optional by Chakra's defineStyleConfig, but zimmButton.css.ts
    // always passes a variants object with an `icon` entry — guaranteed non-null at runtime.
    const icon = Button.variants!.icon as Record<string, unknown>;
    const disabledState = icon._disabled as Record<string, unknown>;
    expect(disabledState.opacity).toBe(OPACITY_ICON_DISABLED);
  });

  test("State 5 — the icon variant's focus-visible outline is genuinely different from its default (resting) outline, not merely a separate key", () => {
    const icon = Button.variants!.icon as Record<string, unknown>;
    const focusVisible = icon._focusVisible as Record<string, unknown>;
    // The resting/default icon style declares no top-level `outline` at all (bg/border/color/
    // transition only — see zimmButton.css.ts) — only _focusVisible adds one. Comparing the two
    // resolved values directly (rather than assuming focus differs from default because Chakra
    // models them as separate keys) proves the two states are actually visually different.
    expect(icon.outline).toBeUndefined();
    expect(focusVisible.outline).toBe('var(--zimm-focus-ring)');
    expect(focusVisible.outline).not.toBe(icon.outline);
  });
});

