import type { Meta, StoryObj } from '@storybook/react-webpack5';
import React, { useState } from 'react';
import { expect, userEvent, within } from 'storybook/test';
import { ZimmQuantityStepper } from '.';

const meta: Meta<typeof ZimmQuantityStepper> = {
  title: 'Commerce/ZimmQuantityStepper',
  component: ZimmQuantityStepper,
  parameters: { layout: 'padded' },
};

export default meta;

type Story = StoryObj<typeof ZimmQuantityStepper>;
type StepperArgs = React.ComponentProps<typeof ZimmQuantityStepper>;

/**
 * Local-state wrapper so a click visibly moves the rendered quantity — ZimmQuantityStepper is a
 * controlled component (see index.tsx), it never holds its own quantity state. `setQuantity`
 * matches `onDecrement`/`onIncrement`'s `(nextQuantity: number) => void` signature directly, so
 * no extra wrapper function is needed for either callback.
 */
const InteractiveStepper = (args: StepperArgs) => {
  const [quantity, setQuantity] = useState(args.quantity);
  return <ZimmQuantityStepper {...args} quantity={quantity} onDecrement={setQuantity} onIncrement={setQuantity} />;
};

/** Mid-range: both buttons enabled. Exercises increment then decrement. */
export const Default: Story = {
  render: (args) => <InteractiveStepper {...args} />,
  args: {
    quantity: 3,
    max: 5,
    onDecrement: () => {},
    onIncrement: () => {},
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const increment = canvas.getByRole('button', { name: 'Increase quantity' });
    const decrement = canvas.getByRole('button', { name: 'Decrease quantity' });

    await expect(canvas.getByText('3')).toBeInTheDocument();

    await userEvent.click(increment);
    await expect(canvas.getByText('4')).toBeInTheDocument();

    await userEvent.click(decrement);
    await expect(canvas.getByText('3')).toBeInTheDocument();
  },
};

/** AC 1 — quantity at the lower bound: decrement is disabled and clicking it does nothing. */
export const AtMinimum: Story = {
  render: (args) => <InteractiveStepper {...args} />,
  args: {
    quantity: 1,
    max: 5,
    onDecrement: () => {},
    onIncrement: () => {},
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const decrement = canvas.getByRole('button', { name: 'Decrease quantity' });

    await expect(decrement).toHaveAttribute('aria-disabled', 'true');

    await userEvent.click(decrement);
    await expect(canvas.getByText('1')).toBeInTheDocument();

    // Increment is unaffected by the lower bound.
    await userEvent.click(canvas.getByRole('button', { name: 'Increase quantity' }));
    await expect(canvas.getByText('2')).toBeInTheDocument();
  },
};

/** AC 3 — quantity at the upper bound: increment is disabled, decrement stays enabled. */
export const AtMaximum: Story = {
  args: {
    quantity: 5,
    max: 5,
    onDecrement: () => {},
    onIncrement: () => {},
  },
};

/** AC 4 — fully out-of-stock / unavailable: both buttons disabled and dimmed, regardless of
 *  where quantity sits between min and max. */
export const Unavailable: Story = {
  args: {
    quantity: 3,
    max: 5,
    isUnavailable: true,
    onDecrement: () => {},
    onIncrement: () => {},
  },
};

