1	import React, { type CSSProperties } from 'react';
2	import {
3	  Button as ChakraButton,
4	  IconButton,
5	  chakra,
6	  useStyleConfig,
7	  useMultiStyleConfig,
8	  type SystemStyleObject,
9	} from '@chakra-ui/react';
10	import { ZimmIcon } from '../zimmIcon';
11	import type { ZimmIconType, ZimmIconSize } from '../zimmIcon';
12	
13	// All hover/press/focus/disabled interaction states live in zimmButton.css.ts, co-located
14	// beside this file. ZimmButton is a thin mapping layer: Zimmermann props (inverse,
15	// large/medium) → Chakra variant/size names that zimmButton.css.ts recognises.
16	
17	type ZimmButtonBaseProps = {
18	  /** Visible label (primary/secondary) or aria-label (icon variant — no visible text). */
19	  label: string;
20	  type?: 'button' | 'submit' | 'reset';
21	  disabled?: boolean;
22	  /**
23	   * Renders the disabled *appearance* while keeping the button focusable and in the Tab
24	   * order (A10) — HTML `disabled` removes it from the accessibility tree entirely, so screen
25	   * reader users can never reach it to hear why the action is unavailable. `onClick` is
26	   * suppressed here rather than by the DOM. Prefer this over `disabled` for
27	   * unavailable-but-explainable states (e.g. Add to Bag with an out-of-stock size selected).
28	   *
29	   * No recipe change is needed: Chakra's `_disabled` pseudo already expands to
30	   * `&:disabled, &[disabled], &[aria-disabled=true], &[data-disabled]`.
31	   */
32	  ariaDisabled?: boolean;
33	  inverse?: boolean;
34	  onClick?: () => void;
35	  style?: CSSProperties;
36	  /** Chakra `sx` passthrough — for a caller-owned recipe part, not a one-off inline style. */
37	  sx?: SystemStyleObject;
38	};
39	
40	type ZimmLabelButtonProps = ZimmButtonBaseProps & {
41	  variant?: 'primary' | 'secondary' | 'social';
42	  /** 'large' = 52px fixed · 'medium' = 40px fixed · 'adaptive' = 40px mobile → 52px desktop
43	   *  (same responsive size as the social variant, applied to primary/secondary colours). */
44	  size?: 'large' | 'medium' | 'adaptive';
45	  fullWidth?: boolean;
46	  /** Links an explanatory message element by id so screen readers announce it on focus. */
47	  ariaDescribedBy?: string;
48	  /** primary/secondary only. Optional icon rendered before the label. Pass a ZimmIcon or any
49	   *  React node. */
50	  iconLeading?: React.ReactNode;
51	  /** primary/secondary only. Optional icon rendered after the label. Pass a ZimmIcon or any
52	   *  React node. */
53	  iconTrailing?: React.ReactNode;
54	  /**
55	   * variant="social" only — matches ZimmSocialButton's own `icon` prop exactly (same name,
56	   * same `React.ReactNode` shape), so migrating a `<ZimmSocialButton icon={...} .../>` call
57	   * site to `<ZimmButton variant="social" icon={...} .../>` needs no prop renaming.
58	   */
59	  icon?: React.ReactNode;
60	  /**
61	   * variant="social" only — sizes the fixed box `icon`'s SVG is forced to fill
62	   * (ZimmSocialButton's recipe; Chakra's createIcon renders at 1em×1em by default, so
63	   * without a fixed box the icon would scale with the button's own responsive font-size
64	   * instead of staying a constant size). Defaults to 'md' (16px), matching the only size
65	   * ever confirmed by Figma for the Apple/Google auth buttons. Ignored for every other
66	   * variant. Reach for this first — only fall back to `iconSx` below when a Figma spec
67	   * genuinely doesn't match one of sm/md/lg/xl.
68	   */
69	  iconSize?: ZimmIconSize;
70	  /**
71	   * variant="social" only — escape hatch for the icon box when `iconSize`'s four token
72	   * values (12/16/20/24px) don't cover a genuinely one-off size. Merges on top of the
73	   * `iconSize`-resolved box (same `sx`-over-`__css` precedence this file's own top-level
74	   * `sx` prop already relies on), so e.g. `iconSx={{ width: '18px', height: '18px' }}`
75	   * overrides just the dimensions without losing the '& svg' fill rule underneath. Prefer
76	   * `iconSize` whenever the value is one of the four registered sizes — this is for the
77	   * genuine gap, not a shortcut around the token scale.
78	   */
79	  iconSx?: SystemStyleObject;
80	};
81	
82	type ZimmIconButtonProps = ZimmButtonBaseProps & {
83	  variant: 'icon';
84	  icon: ZimmIconType;
85	  /** Icon render size — one of the iconSizes keys ('sm' | 'md' | 'lg'). Defaults to 'md' (16px). */
86	  size?: ZimmIconSize;
87	};
88	
89	type ZimmButtonProps = ZimmLabelButtonProps | ZimmIconButtonProps;
90	
91	const ICON_SIZE_DEFAULT: ZimmIconSize = 'md';
92	
93	/** Atom — labelled button (primary/secondary/social) or icon-only button. All visual states
94	 *  are handled by `zimmButton.css.ts` (co-located beside this file) — no React state for hover/press/focus.
95	 *  Labelled variants accept optional `iconLeading` and `iconTrailing` nodes rendered either
96	 *  side of the label; gap between icon and text is set by the button's flex gap in baseStyle. */
97	export const ZimmButton = (props: ZimmButtonProps) => {
98	  const { label, type = 'button', disabled = false, ariaDisabled = false, inverse = false, onClick, style, sx } = props;
99	  // aria-disabled leaves the button clickable at the DOM level, so the no-op has to happen here.
100	  const handleClick = ariaDisabled ? undefined : onClick;
101	  const ariaDisabledAttr = ariaDisabled || undefined;
102	  const labelStyle = useStyleConfig('ZimmButtonLabel', {});
103	  // Called unconditionally (Rules of Hooks) even though only the variant="social" branch below
104	  // uses it. 'iconSize' only exists on ZimmLabelButtonProps, not ZimmIconButtonProps, hence the
105	  // `in` guard. size defaults to 'md' explicitly — see zimmSocialButton/index.tsx's own comment
106	  // on why this doesn't rely on the recipe's defaultProps.
107	  const iconSizeProp = 'iconSize' in props ? props.iconSize : undefined;
108	  const socialStyles = useMultiStyleConfig('ZimmSocialButton', { size: iconSizeProp ?? 'md' });
109	
110	  if (props.variant === 'icon') {
111	    return (
112	      <IconButton
113	        aria-label={label}
114	        type={ariaDisabled ? 'button' : type}
115	        isDisabled={disabled}
116	        aria-disabled={ariaDisabledAttr}
117	        onClick={handleClick}
118	        variant={inverse ? 'iconInverse' : 'icon'}
119	        size="icon"
120	        icon={<ZimmIcon type={props.icon} size={props.size ?? ICON_SIZE_DEFAULT} aria-hidden={true} />}
121	        style={style}
122	        sx={sx}
123	      />
124	    );
125	  }
126	
127	  const variant = props.variant ?? 'primary';
128	  const ariaDescribedBy = 'ariaDescribedBy' in props ? props.ariaDescribedBy : undefined;
129	  // fullWidth defaults to true for variant="social" (ZimmSocialButton was always full-width,
130	  // Figma-confirmed, no known narrower case) but stays a real, overridable prop — an explicit
131	  // fullWidth={false} still wins. Every other variant is unchanged: opt-in, default false.
132	  const fullWidth = props.fullWidth ?? variant === 'social' ? '100%' : undefined;
133	
134	  if (variant === 'social') {
135	    return (
136	      <ChakraButton
137	        type={ariaDisabled ? 'button' : type}
138	        isDisabled={disabled}
139	        aria-disabled={ariaDisabledAttr}
140	        aria-label={label}
141	        aria-describedby={ariaDescribedBy}
142	        onClick={handleClick}
143	        variant="social"
144	        size="social"
145	        width={fullWidth}
146	        style={style}
147	        sx={sx}
148	      >
149	        {/* Same container>icon+label DOM shape as ZimmSocialButton itself — reused rather than
150	            reinvented, so this carries over its exact, already-confirmed layout instead of a
151	            new "should be equivalent" structure. */}
152	        <chakra.span __css={socialStyles.container}>
153	          <chakra.span aria-hidden={true} __css={socialStyles.icon} sx={props.iconSx}>
154	            {props.icon}
155	          </chakra.span>
156	          <chakra.span __css={socialStyles.label}>{label}</chakra.span>
157	        </chakra.span>
158	      </ChakraButton>
159	    );
160	  }
161	
162	  // size/chakraVariant are only meaningful for primary/secondary from here — the social case
163	  // already returned above with literal 'social'/'social'.
164	  const size = props.size === 'adaptive' ? 'social' : props.size === 'medium' ? 'sm' : 'lg';
165	  // Maps inverse prop to the *Inverse variant suffix defined in zimmButton.css.ts.
166	  const chakraVariant = `${variant}${inverse ? 'Inverse' : ''}`;
167	
168	  return (
169	    <ChakraButton
170	      type={ariaDisabled ? 'button' : type}
171	      isDisabled={disabled}
172	      aria-disabled={ariaDisabledAttr}
173	      // aria-label makes the accessible name explicit so VoiceOver doesn't read
174	      // CSS text-transform:uppercase as an acronym (e.g. "A-D-D to bag").
175	      aria-label={label}
176	      aria-describedby={ariaDescribedBy}
177	      onClick={handleClick}
178	      variant={chakraVariant}
179	      size={size}
180	      width={fullWidth}
181	      style={style}
182	      sx={sx}
183	    >
184	      {props.iconLeading && (
185	        <chakra.span aria-hidden={true} display="flex" alignItems="center" justifyContent="center" flexShrink={0}>
186	          {props.iconLeading}
187	        </chakra.span>
188	      )}
189	      <chakra.span __css={labelStyle}>{label}</chakra.span>
190	      {props.iconTrailing && (
191	        <chakra.span aria-hidden={true} display="flex" alignItems="center" justifyContent="center" flexShrink={0}>
192	          {props.iconTrailing}
193	        </chakra.span>
194	      )}
195	    </ChakraButton>
196	  );
197	};
198

