import {
  Button as ChakraButton,
  IconButton,
  chakra,
  useStyleConfig,
  useMultiStyleConfig,
  type SystemStyleObject,
} from '@chakra-ui/react';
import { ZimmIcon } from '../zimmIcon';
import type { ZimmIconType, ZimmIconSize } from '../zimmIcon';

// All hover/press/focus/disabled interaction states live in zimmButton.css.ts, co-located
// beside this file. ZimmButton is a thin mapping layer: Zimmermann props (inverse,
// large/medium) → Chakra variant/size names that zimmButton.css.ts recognises.

type ZimmButtonBaseProps = {
  /** Visible label (primary/secondary) or aria-label (icon variant — no visible text). */
  label: string;
  type?: 'button' | 'submit' | 'reset';
  disabled?: boolean;
  /**
   * Renders the disabled *appearance* while keeping the button focusable and in the Tab
   * order (A10) — HTML `disabled` removes it from the accessibility tree entirely, so screen
   * reader users can never reach it to hear why the action is unavailable. `onClick` is
   * suppressed here rather than by the DOM. Prefer this over `disabled` for
   * unavailable-but-explainable states (e.g. Add to Bag with an out-of-stock size selected).
   *
   * No recipe change is needed: Chakra's `_disabled` pseudo already expands to
   * `&:disabled, &[disabled], &[aria-disabled=true], &[data-disabled]`.
   */
  ariaDisabled?: boolean;
  inverse?: boolean;
  onClick?: () => void;
  style?: CSSProperties;
  /** Chakra `sx` passthrough — for a caller-owned recipe part, not a one-off inline style. */
  sx?: SystemStyleObject;
};

type ZimmLabelButtonProps = ZimmButtonBaseProps & {
  variant?: 'primary' | 'secondary' | 'social';
  /** 'large' = 52px fixed · 'medium' = 40px fixed · 'adaptive' = 40px mobile → 52px desktop
   *  (same responsive size as the social variant, applied to primary/secondary colours). */
  size?: 'large' | 'medium' | 'adaptive';
  fullWidth?: boolean;
  /** Links an explanatory message element by id so screen readers announce it on focus. */
  ariaDescribedBy?: string;
  /** primary/secondary only. Optional icon rendered before the label. Pass a ZimmIcon or any
   *  React node. */
  iconLeading?: React.ReactNode;
  /** primary/secondary only. Optional icon rendered after the label. Pass a ZimmIcon or any
   *  React node. */
  iconTrailing?: React.ReactNode;
  /**
   * variant="social" only — matches ZimmSocialButton's own `icon` prop exactly (same name,
   * same `React.ReactNode` shape), so migrating a `<ZimmSocialButton icon={...} .../>` call
   * site to `<ZimmButton variant="social" icon={...} .../>` needs no prop renaming.
   */
  icon?: React.ReactNode;
  /**
   * variant="social" only — sizes the fixed box `icon`'s SVG is forced to fill
   * (ZimmSocialButton's recipe; Chakra's createIcon renders at 1em×1em by default, so
   * without a fixed box the icon would scale with the button's own responsive font-size
   * instead of staying a constant size). Defaults to 'md' (16px), matching the only size
   * ever confirmed by Figma for the Apple/Google auth buttons. Ignored for every other
   * variant. Reach for this first — only fall back to `iconSx` below when a Figma spec
   * genuinely doesn't match one of sm/md/lg/xl.
   */
  iconSize?: ZimmIconSize;
  /**
   * variant="social" only — escape hatch for the icon box when `iconSize`'s four token
   * values (12/16/20/24px) don't cover a genuinely one-off size. Merges on top of the
   * `iconSize`-resolved box (same `sx`-over-`__css` precedence this file's own top-level
   * `sx` prop already relies on), so e.g. `iconSx={{ width: '18px', height: '18px' }}`
   * overrides just the dimensions without losing the '& svg' fill rule underneath. Prefer
   * `iconSize` whenever the value is one of the four registered sizes — this is for the
   * genuine gap, not a shortcut around the token scale.
   */
  iconSx?: SystemStyleObject;
};

type ZimmIconButtonProps = ZimmButtonBaseProps & {
  variant: 'icon';
  icon: ZimmIconType;
  /** Icon render size — one of the iconSizes keys ('sm' | 'md' | 'lg'). Defaults to 'md' (16px). */
  size?: ZimmIconSize;
};

type ZimmButtonProps = ZimmLabelButtonProps | ZimmIconButtonProps;

const ICON_SIZE_DEFAULT: ZimmIconSize = 'md';

/** Atom — labelled button (primary/secondary/social) or icon-only button. All visual states
 *  are handled by `zimmButton.css.ts` (co-located beside this file) — no React state for hover/press/focus.
 *  Labelled variants accept optional `iconLeading` and `iconTrailing` nodes rendered either
 *  side of the label; gap between icon and text is set by the button's flex gap in baseStyle. */
export const ZimmButton = (props: ZimmButtonProps) => {
  const { label, type = 'button', disabled = false, ariaDisabled = false, inverse = false, onClick, style, sx } = props;
  // aria-disabled leaves the button clickable at the DOM level, so the no-op has to happen here.
  const handleClick = ariaDisabled ? undefined : onClick;
  const ariaDisabledAttr = ariaDisabled || undefined;
  const labelStyle = useStyleConfig('ZimmButtonLabel', {});
  // Called unconditionally (Rules of Hooks) even though only the variant="social" branch below
  // uses it. 'iconSize' only exists on ZimmLabelButtonProps, not ZimmIconButtonProps, hence the
  // `in` guard. size defaults to 'md' explicitly — see zimmSocialButton/index.tsx's own comment
  // on why this doesn't rely on the recipe's defaultProps.
  const iconSizeProp = 'iconSize' in props ? props.iconSize : undefined;
  const socialStyles = useMultiStyleConfig('ZimmSocialButton', { size: iconSizeProp ?? 'md' });

  if (props.variant === 'icon') {
    return (
      <IconButton
        aria-label={label}
        type={ariaDisabled ? 'button' : type}
        isDisabled={disabled}
        aria-disabled={ariaDisabledAttr}
        onClick={handleClick}
        variant={inverse ? 'iconInverse' : 'icon'}
        size="icon"
        icon={<ZimmIcon type={props.icon} size={props.size ?? ICON_SIZE_DEFAULT} aria-hidden={true} />}
        style={style}
        sx={sx}
      />
    );
  }

  const variant = props.variant ?? 'primary';
  const ariaDescribedBy = 'ariaDescribedBy' in props ? props.ariaDescribedBy : undefined;
  // fullWidth defaults to true for variant="social" (ZimmSocialButton was always full-width,
  // Figma-confirmed, no known narrower case) but stays a real, overridable prop — an explicit
  // fullWidth={false} still wins. Every other variant is unchanged: opt-in, default false.
  const fullWidth = props.fullWidth ?? variant === 'social' ? '100%' : undefined;

  if (variant === 'social') {
    return (
      <ChakraButton
        type={ariaDisabled ? 'button' : type}
        isDisabled={disabled}
        aria-disabled={ariaDisabledAttr}
        aria-label={label}
        aria-describedby={ariaDescribedBy}
        onClick={handleClick}
        variant="social"
        size="social"
        width={fullWidth}
        style={style}
        sx={sx}
      >
        {/* Same container>icon+label DOM shape as ZimmSocialButton itself — reused rather than
            reinvented, so this carries over its exact, already-confirmed layout instead of a
            new "should be equivalent" structure. */}
        <chakra.span __css={socialStyles.container}>
          <chakra.span aria-hidden={true} __css={socialStyles.icon} sx={props.iconSx}>
            {props.icon}
          </chakra.span>
          <chakra.span __css={socialStyles.label}>{label}</chakra.span>
        </chakra.span>
      </ChakraButton>
    );
  }

  // size/chakraVariant are only meaningful for primary/secondary from here — the social case
  // already returned above with literal 'social'/'social'.
  const size = props.size === 'adaptive' ? 'social' : props.size === 'medium' ? 'sm' : 'lg';
  // Maps inverse prop to the *Inverse variant suffix defined in zimmButton.css.ts.
  const chakraVariant = `${variant}${inverse ? 'Inverse' : ''}`;

  return (
    <ChakraButton
      type={ariaDisabled ? 'button' : type}
      isDisabled={disabled}
      aria-disabled={ariaDisabledAttr}
      // aria-label makes the accessible name explicit so VoiceOver doesn't read
      // CSS text-transform:uppercase as an acronym (e.g. "A-D-D to bag").
      aria-label={label}
      aria-describedby={ariaDescribedBy}
      onClick={handleClick}
      variant={chakraVariant}
      size={size}
      width={fullWidth}
      style={style}
      sx={sx}
    >
      {props.iconLeading && (
        <chakra.span aria-hidden={true} display="flex" alignItems="center" justifyContent="center" flexShrink={0}>
          {props.iconLeading}
        </chakra.span>
      )}
      <chakra.span __css={labelStyle}>{label}</chakra.span>
      {props.iconTrailing && (
        <chakra.span aria-hidden={true} display="flex" alignItems="center" justifyContent="center" flexShrink={0}>
          {props.iconTrailing}
        </chakra.span>
      )}
    </ChakraButton>
  );
};

import { defineStyleConfig } from '@chakra-ui/react';
import { breakpoints } from 'app/theme/foundation/gridSystem';

const BUTTON_PRESSED = 'var(--zimm-color-action-primary-bg-pressed)';
// No --zimm-focus-ring-inverse CSS var yet — inline until designer adds one to zimmTokens.
const FOCUS_RING_INVERSE = 'var(--zimm-border-width-default) solid var(--zimm-color-action-primary-text)';

// Icon-variant opacity levels. No foundation opacity token covers element-level opacity
// (colors.opacity holds RGBA overlays, not multipliers), so named constants are the
// correct pattern per conventions.md > "No magic numbers or strings."
const OPACITY_ICON_HOVER = 0.6;
const OPACITY_ICON_DISABLED = 0.4;
// 0.15s, matching baseStyle. Deliberately NOT var(--zimm-motion-duration-fast) (200ms):
// see baseStyle's transition comment above — that decision was to leave 0.15s as-is pending
// the UI designer rather than retime silently, and motion.ts is itself marked provisional.
// Retiming only the icon variants would leave this file running two different durations.
// One constant so icon/iconInverse cannot drift.
const ICON_TRANSITION = 'opacity 0.15s ease';

// fontFamily/fontWeight/lineHeight/letterSpacing/textTransform come from sizes.lg/sm's
// textStyle (below), not here — button always renders with a size (defaultProps.size
// is 'lg', there's no sizeless render path), so a duplicate fallback here would only
// ever mask the per-size textStyle value instead of letting it apply.
const baseStyle = {
  borderRadius: 0,
  // Layout — matches Figma: display:inline-flex; justify-content:center; align-items:center;
  // gap:var(--alias-space-100,4px) — universal across all sizes and variants.
  display: 'inline-flex',
  alignItems: 'center',
  justifyContent: 'center',
  gap: 'var(--zimm-scale-2xs)',
  overflow: 'clip',
  // 0.15s matches no motion token (fast 200ms / default 300ms) — left as-is
  // pending the UI designer's confirmation rather than retimed silently.
  transition: 'background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease',
  // Focus ring per Handover button.md §focus: outline only, no background change.
  // Replaces the previous outline:none + bg-swap, which gave the primary variant an
  // invisible focus state (#191919 default vs #000000 focus) — a WCAG 2.4.7 failure.
  // Light-mode ring (border-focus). Dark-surface / inverse ring (grey-white) is the
  // separate deferred inverse-focus item, owned with the UI designer.
  _focusVisible: {
    outline: 'var(--zimm-focus-ring)',
    outlineOffset: 'var(--zimm-focus-ring-offset-default)',
    boxShadow: 'none',
  },
};

const variants = {
  // Figma node 901:2897 — primary has no border; solid bg only.
  primary: {
    bg: 'var(--zimm-color-text-default)',
    color: 'var(--zimm-color-text-inverse)',
    _hover: {
      bg: 'var(--zimm-color-text-inverse-grey)',
      _disabled: { bg: 'var(--zimm-color-border-secondary)' },
    },
    _active: { bg: BUTTON_PRESSED },
    _disabled: {
      bg: 'var(--zimm-color-border-secondary)',
      // Figma: disabled text = #969696 (action-primary-text-disabled), not white
      color: 'var(--zimm-color-action-primary-text-disabled)',
      opacity: 1,
      cursor: 'not-allowed',
    },
    // Focus ring inherited from baseStyle (2px offset), per Handover button.md.
  },
  primaryInverse: {
    bg: 'var(--zimm-color-action-primary-text)',
    color: 'var(--zimm-color-action-primary-bg-default)',
    border: 'none',
    _hover: {
      bg: 'var(--zimm-color-action-secondary-bg-hover)',
      _disabled: { bg: 'var(--zimm-color-action-primary-bg-disabled)' },
    },
    _active: {
      bg: BUTTON_PRESSED,
      color: 'var(--zimm-color-action-primary-text)',
    },
    _disabled: {
      bg: 'var(--zimm-color-action-primary-bg-disabled)',
      color: 'var(--zimm-color-action-primary-text-disabled)',
      opacity: 1,
      cursor: 'not-allowed',
    },
    _focusVisible: {
      outline: FOCUS_RING_INVERSE,
      outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      boxShadow: 'none',
    },
  },
  secondary: {
    bg: 'transparent',
    color: 'var(--zimm-color-text-default)',
    border: 'var(--zimm-border-width-default) solid',
    borderColor: 'var(--zimm-color-text-default)',
    _hover: {
      bg: 'var(--zimm-color-bg-01)',
      borderColor: 'var(--zimm-color-text-default)',
      _disabled: { bg: 'transparent', borderColor: 'var(--zimm-color-text-inverse-grey)' },
    },
    _active: {
      bg: BUTTON_PRESSED,
      borderColor: BUTTON_PRESSED,
      color: 'var(--zimm-color-text-inverse)',
    },
    _disabled: {
      bg: 'transparent',
      borderColor: 'var(--zimm-color-text-inverse-grey)',
      color: 'var(--zimm-color-text-muted)',
      opacity: 1,
      cursor: 'not-allowed',
    },
    // Handover button.md §focus: outline only (no background change); 3px offset on
    // secondary to clear its 1px border. Stated explicitly rather than relying on
    // baseStyle merge, so the ring can't be lost to variant-override semantics.
    _focusVisible: {
      outline: 'var(--zimm-focus-ring)',
      outlineOffset: 'var(--zimm-focus-ring-offset-secondary)',
      boxShadow: 'none',
    },
  },
  secondaryInverse: {
    bg: 'transparent',
    color: 'var(--zimm-color-action-primary-text)',
    border: 'var(--zimm-border-width-default) solid',
    borderColor: 'var(--zimm-color-action-primary-text)',
    _hover: {
      bg: 'var(--zimm-color-action-secondary-bg-hover)',
      // Figma: hover state uses dark text (default) on the lighter hover bg
      color: 'var(--zimm-color-text-default)',
      _disabled: {
        bg: 'transparent',
        borderColor: 'var(--zimm-color-action-secondary-text-disabled)',
      },
    },
    _active: {
      bg: BUTTON_PRESSED,
      borderColor: BUTTON_PRESSED,
      color: 'var(--zimm-color-action-primary-text)',
    },
    _disabled: {
      bg: 'transparent',
      borderColor: 'var(--zimm-color-action-secondary-text-disabled)',
      color: 'var(--zimm-color-action-secondary-text-disabled)',
      opacity: 1,
      cursor: 'not-allowed',
    },
    _focusVisible: {
      outline: FOCUS_RING_INVERSE,
      outlineOffset: 'var(--zimm-focus-ring-offset-secondary)',
      boxShadow: 'none',
    },
  },
  // Social identity provider button (Apple, Google) — outlined, full-width, with leading icon.
  // Root layout (display, gap, width) lives here so all button states are in one file.
  // Sub-element sizing (icon span, label typography) is owned by ZimmSocialButton's recipe.
  // whiteSpace: normal — Chakra's Button baseStyle sets nowrap, which causes long labels
  // (e.g. "Sign in with Google") to overflow both sides of a centered flex container.
  // justifyContent/alignItems repeated from baseStyle — Chakra's extendTheme merge can
  // silently drop baseStyle values when a variant is present; explicit wins here.
  social: {
    whiteSpace: 'normal',
    justifyContent: 'center',
    alignItems: 'center',
    bg: 'transparent',
    border: 'var(--zimm-border-width-default) solid',
    borderColor: 'var(--zimm-color-action-secondary-border)',
    color: 'var(--zimm-color-action-secondary-text)',
    _hover: {
      bg: 'var(--zimm-color-bg-01)',
      _disabled: { bg: 'transparent' },
    },
    _active: { bg: 'var(--zimm-color-bg-01)' },
    _disabled: {
      opacity: OPACITY_ICON_DISABLED,
      cursor: 'not-allowed',
      bg: 'transparent',
      borderColor: 'var(--zimm-color-action-secondary-border)',
    },
    _focusVisible: {
      outline: 'var(--zimm-focus-ring)',
      outlineOffset: 'var(--zimm-focus-ring-offset-secondary)',
      boxShadow: 'none',
    },
  },
  // Icon-only variant — opacity-based hover; transition overrides baseStyle to include opacity.
  icon: {
    bg: 'transparent',
    border: 'none',
    color: 'var(--zimm-color-action-primary-bg-default)',
    transition: ICON_TRANSITION,
    _hover: {
      bg: 'transparent',
      opacity: OPACITY_ICON_HOVER,
    },
    _active: {
      bg: 'transparent',
      opacity: 1,
    },
    _disabled: {
      bg: 'transparent',
      opacity: OPACITY_ICON_DISABLED,
      cursor: 'not-allowed',
    },
    _focusVisible: {
      outline: 'var(--zimm-focus-ring)',
      outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      boxShadow: 'none',
    },
  },
  iconInverse: {
    bg: 'transparent',
    border: 'none',
    color: 'var(--zimm-color-action-primary-text)',
    transition: ICON_TRANSITION,
    _hover: {
      bg: 'transparent',
      opacity: OPACITY_ICON_HOVER,
    },
    _active: {
      bg: 'transparent',
      opacity: 1,
    },
    _disabled: {
      bg: 'transparent',
      opacity: OPACITY_ICON_DISABLED,
      cursor: 'not-allowed',
    },
    _focusVisible: {
      outline: FOCUS_RING_INVERSE,
      outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      boxShadow: 'none',
    },
  },
};

// lg button: Handover action tokens confirmed by Figma auth drawer (node 40001855:28911) —
// 52px height, 32px padding X, 4px gap (--alias-space-100), 80px min-width.
// height/paddingX use foundation tokens; gap maps to --zimm-scale-2xs (4px).
// min-width has no --zimm-size-action-width-min token yet — provisional constant below.
//
// sm button: confirmed by Figma node 901:2897 — 40px height, 20px padding X. Both now
// use foundation tokens (action-height-md, action-padding-h-md) instead of raw values.
const BTN_MIN_WIDTH_LG = '80px'; // audit-allow: provisional — pending --zimm-size-action-width-min token

// `textStyle` sets fontFamily/fontWeight/lineHeight/letterSpacing/textTransform via
// Chakra's expansion pass. BUT extendTheme deep-merges our sizes with Chakra's built-in
// Button sizes, and Chakra's default lg has `fontSize: 'lg'` (1.125rem = 18px) and sm
// has `fontSize: 'sm'` (0.875rem = 14px). Because direct CSS props applied after the
// textStyle expansion win in Chakra's style pipeline, the merged `fontSize` from Chakra's
// default overrides the textStyle-derived value. Fix: set `fontSize` explicitly here using
// the zimm CSS var so it overwrites the leaked default and the final rendered size matches
// typography.ts (button = 14px, buttonSm = 12px).
const sizes = {
  lg: {
    h: 'var(--zimm-size-action-height-lg)', // 52px — confirmed by Figma + Handover
    minW: BTN_MIN_WIDTH_LG, // 80px — Figma --alias-size-action-width-min, pending token
    px: 'var(--zimm-size-action-padding-h-lg)', // 32px — confirmed by Figma + Handover
    // fontSize / fontWeight / lineHeight explicitly set to override Chakra's deep-merged
    // Button.sizes.lg defaults (fontSize:'lg'=1.125rem, fontWeight:'semibold'=600,
    // lineHeight:'1.2') — same issue as the baseStyle fontWeight: these leak through
    // extendTheme's deep-merge even when textStyle sets the correct values.
    fontSize: 'var(--zimm-font-size-2xs)', // 14px
    fontWeight: 'var(--zimm-font-weight-medium)', // 500
    lineHeight: 'var(--zimm-font-lineheight-3xs)', // 16px
    textStyle: 'button',
  },
  sm: {
    h: 'var(--zimm-size-action-height-md)', // 40px — confirmed by Figma 901:2897
    px: 'var(--zimm-size-action-padding-h-md)', // 20px — confirmed by Figma 901:2897
    fontSize: 'var(--zimm-font-size-3xs)', // 12px
    fontWeight: 'var(--zimm-font-weight-medium)', // 500
    lineHeight: 'var(--zimm-font-lineheight-2xs)', // 18px
    textStyle: 'buttonSm',
  },
  // Social button responsive size. Figma confirms height/typography step at the md
  // breakpoint, but horizontal padding is 32px at every breakpoint — NOT responsive.
  // Corrected 2026-09: the previous version of this comment claimed padding also stepped
  // down to 20px on mobile ("Figma confirms all three variants"); live Figma inspection
  // showed that was wrong — px was always meant to be var(--zimm-size-action-padding-h-lg).
  // Mobile: 40px h, 32px px, buttonSm (12px/500/18px lh)
  // Desktop (md+): 52px h, 32px px, button (14px/500/16px lh)
  // Also used by primary/secondary buttons inside the auth drawer (size="adaptive")
  // via ZimmButton's adaptive→social size mapping — same tokens, different variant colours.
  social: {
    // h (explicit fixed height) guarantees the flex container has a known height so
    // align-items:center always has space to distribute. minH alone can resolve to nothing
    // if the CSS variable hasn't loaded, leaving the button at content height with no
    // centering space. whiteSpace:normal (from the social variant) still allows text wrapping
    // if the label needs it; overflow:clip (from baseStyle) handles any rare overflow.
    h: 'var(--zimm-size-action-height-md)',
    // Constant across breakpoints — see the comment above this size. Not var(--...-h-md)
    // (20px): that's the mobile action-height tier's own padding token, but this button's
    // horizontal padding was never meant to shrink with it.
    px: 'var(--zimm-size-action-padding-h-lg)',
    fontSize: 'var(--zimm-font-size-3xs)',
    fontWeight: 'var(--zimm-font-weight-medium)',
    lineHeight: 'var(--zimm-font-lineheight-2xs)',
    textStyle: 'buttonSm',
    [`@media (min-width: ${breakpoints.md})`]: {
      h: 'var(--zimm-size-action-height-lg)',
      fontSize: 'var(--zimm-font-size-2xs)',
      lineHeight: 'var(--zimm-font-lineheight-3xs)',
      textStyle: 'button',
    },
  },
  // WCAG 2.2 AA SC 2.5.8 — 24px minimum target size. SFCC-55's accessibility note names this
  // control specifically ("the minimum size of that email sign up button").
  //
  // minW/minH, NOT padding: Chakra's IconButton hard-sets `padding: "0"` as a *style prop*, and
  // style props merge after __css, so any p/px/py declared here is silently discarded. The
  // previous `p: 'xs'` read as a 32px target and rendered 16x16 — the icon's own boxSize.
  //
  // var, not 'xl': min-width/height resolve through theme.sizes (xl = 36rem = 576px), not
  // theme.space. Same rule and same token as clearButton in zimmTextInput.ts, which is the
  // sibling control in the same trailing slot.
  icon: {
    h: 'auto',
    minW: 'var(--zimm-scale-xl)',
    minH: 'var(--zimm-scale-xl)',
  },
};

export const Button = defineStyleConfig({
  baseStyle,
  variants,
  sizes,
  defaultProps: {
    variant: 'primary',
    size: 'lg',
  },
});

// Figma: every button label carries text-box-trim:trim-both + text-box-edge:cap_alphabetic
// to strip Futura Round's metric whitespace above cap-height and below the alphabetic
// baseline so uppercase glyphs sit at the true visual centre.
export const ZimmButtonLabel = defineStyleConfig({
  baseStyle: {
    flexShrink: 0,
    textBoxTrim: 'trim-both',
    textBoxEdge: 'cap alphabetic',
  },
});

